<div class="page-actions"><div><p class="mb-0">Purchase Request → Approval → Purchase Order → Goods Receipt → Inventory.</p></div><div class="d-flex gap-2"><button class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#prModal">New PR</button><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#poModal">New PO</button></div></div>
<div class="row g-3"><div class="col-lg-6"><div class="card-panel"><h3 class="h6 mb-3">Purchase Requests</h3><div class="table-responsive"><table class="table"><thead><tr><th>Request</th><th>Requester</th><th>Items</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><strong><?= e($r['request_number']) ?></strong><small class="d-block text-secondary"><?= e($r['created_at']) ?></small></td><td><?= e($r['requester_name']) ?></td><td><?= e($r['item_count']) ?></td><td><span class="status-badge"><?= e($r['status']) ?></span></td><td><?php if(in_array($r['status'],['Request','Purchasing'],true)&&\App\Core\Auth::can('purchase.approve')): ?><button class="btn btn-sm btn-outline-success ajax-action" data-url="<?= url('/purchasing/requests/'.$r['id'].'/approve') ?>" data-payload='{"status":"Approved"}'>Approve</button><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="col-lg-6"><div class="card-panel"><h3 class="h6 mb-3">Purchase Orders</h3><div class="table-responsive"><table class="table"><thead><tr><th>PO</th><th>Vendor</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><strong><?= e($o['po_number']) ?></strong><small class="d-block text-secondary"><?= e($o['request_number']??'Direct PO') ?></small></td><td><?= e($o['vendor_name']) ?></td><td><?= e(money($o['total'])) ?></td><td><span class="status-badge <?= $o['status']==='Received'?'success':'' ?>"><?= e($o['status']) ?></span></td><td><?php if($o['status']!=='Received'&&\App\Core\Auth::can('purchase.receive')): ?><button class="btn btn-sm btn-outline-primary receive-po" data-id="<?= $o['id'] ?>" data-number="<?= e($o['po_number']) ?>">Receive</button><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<div class="modal fade" id="prModal"><div class="modal-dialog modal-xl"><form class="modal-content ajax-form" method="post" action="<?= url('/purchasing/requests') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Purchase Request</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3 mb-3"><div class="col-md-4"><label class="form-label">Branch</label><select class="form-select" name="branch_id"><option value="">None</option><?php foreach($branches as $b): ?><option value="<?= $b['id'] ?>"><?= e($b['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-8"><label class="form-label">Notes</label><input class="form-control" name="notes"></div></div><table class="table"><thead><tr><th>Item</th><th>Description</th><th>Qty</th><th>Unit</th><th></th></tr></thead><tbody id="prItems"></tbody></table><button class="btn btn-sm btn-outline-primary" type="button" data-add-row="pr">Add Item</button></div><div class="modal-footer"><button class="btn btn-primary">Submit Request</button></div></form></div></div>
<div class="modal fade" id="poModal"><div class="modal-dialog modal-xl"><form class="modal-content ajax-form" method="post" action="<?= url('/purchasing/orders') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Purchase Order</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3 mb-3"><div class="col-md-4"><label class="form-label">Vendor</label><select class="form-select" name="vendor_id" required><option value="">Select</option><?php foreach($vendors as $v): ?><option value="<?= $v['id'] ?>"><?= e($v['vendor_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Related PR</label><select class="form-select" name="purchase_request_id"><option value="">Direct PO</option><?php foreach($requests as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['request_number'].' · '.$r['status']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Expected Date</label><input class="form-control" type="date" name="expected_date"></div><div class="col-md-4"><label class="form-label">Tax Amount</label><input class="form-control" type="number" step="0.01" name="tax" value="0"></div></div><table class="table"><thead><tr><th>Item</th><th>Description</th><th>Qty</th><th>Unit Price</th><th></th></tr></thead><tbody id="poItems"></tbody></table><button class="btn btn-sm btn-outline-primary" type="button" data-add-row="po">Add Item</button></div><div class="modal-footer"><button class="btn btn-primary">Create PO</button></div></form></div></div>
<div class="modal fade" id="receiveModal"><div class="modal-dialog"><form class="modal-content ajax-form" id="receiveForm" method="post"><?= csrf_field() ?><div class="modal-header"><h5>Receive Purchase Order</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p id="receivePoName"></p><label class="form-label">Receive to Warehouse</label><select class="form-select mb-2" name="warehouse_id" required><?php foreach($warehouses as $w): ?><option value="<?= $w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><textarea class="form-control" name="notes" placeholder="Receipt notes"></textarea><div class="alert alert-info mt-3 mb-0">Semua outstanding stock item pada PO akan diterima ke warehouse ini.</div></div><div class="modal-footer"><button class="btn btn-primary">Receive Goods</button></div></form></div></div>
